205	// resolvedVendorRoot resolves the workspace and its .okf/vendor root through
206	// symlinks and refuses a vendor root that lies outside the workspace (for
207	// example a repository that ships `.okf -> /elsewhere`).
208	func resolvedVendorRoot(workspace string) (string, error) {
209		ws, err := resolvePath(workspace, true)
210		if err != nil {
211			return "", fmt.Errorf("failed to resolve workspace %q: %w", workspace, err)
212		}
213		root, err := resolvePath(VendorRoot(workspace), true)
214		if err != nil {
215			return "", fmt.Errorf("failed to resolve vendor root: %w", err)
216		}
217		if !within(ws, root) {
218			return "", fmt.Errorf("refusing vendor root %q: resolves to %q outside workspace %q", VendorRoot(workspace), root, ws)
219		}
220		return root, nil
221	}
222	
223	// containedPath resolves target (see resolvePath) and returns it only if it
224	// lies strictly inside the already-resolved root.
225	func containedPath(root, target string, followLeaf bool, kind string) (string, error) {
226		resolved, err := resolvePath(target, followLeaf)
227		if err != nil {
228			return "", fmt.Errorf("failed to resolve %s path %q: %w", kind, target, err)
229		}
230		if !within(root, resolved) || resolved == root {
231			return "", fmt.Errorf("refusing %s: %q resolves to %q outside %q", kind, target, resolved, root)
232		}
233		return resolved, nil
234	}
235	
236	// resolvePath returns the absolute path of target with symlinks resolved in its
237	// closest existing ancestor, so paths not yet created resolve too. With
238	// followLeaf false the final element is not resolved, so a symlink at target
239	// is treated as the link itself.
240	func resolvePath(target string, followLeaf bool) (string, error) {
241		abs, err := filepath.Abs(target)
242		if err != nil {
243			return "", err
244		}
245		existing, missing, leaf := abs, "", ""
246		if !followLeaf {
247			existing, leaf = filepath.Dir(abs), filepath.Base(abs)
248		}
249		for {
250			if _, err := os.Lstat(existing); err == nil {
251				break
252			}
253			parent := filepath.Dir(existing)
254			if parent == existing {
255				break
256			}
257			missing = filepath.Join(filepath.Base(existing), missing)
258			existing = parent
259		}
260		resolved, err := filepath.EvalSymlinks(existing)
261		if err != nil {
262			return "", err
263		}
264		return filepath.Join(resolved, missing, leaf), nil
265	}
266	
267	// within reports whether path equals root or lies below it (filepath.Rel, not a
268	// string prefix).
269	func within(root, path string) bool {
270		rel, err := filepath.Rel(root, path)
271		return err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && !filepath.IsAbs(rel)
272	}
