179	func (c *Client) DownloadAndExtract(manifest *BundleManifest, targetDir string) error {
180		req, err := http.NewRequest("GET", manifest.DownloadURL, nil)
181		if err != nil {
182			return err
183		}
184		req.Header.Set("User-Agent", "okf-agent-memory-cli")
185	
186		resp, err := c.HTTPClient.Do(req)
187		if err != nil {
188			return fmt.Errorf("failed to download bundle: %w", err)
189		}
190		defer func() { _ = resp.Body.Close() }()
191	
192		if resp.StatusCode != http.StatusOK {
193			return fmt.Errorf("bundle download failed with HTTP %s", resp.Status)
194		}
195	
196		data, err := io.ReadAll(resp.Body)
197		if err != nil {
198			return fmt.Errorf("error reading bundle stream: %w", err)
199		}
200	
201		calculated := fmt.Sprintf("sha256:%x", sha256.Sum256(data))
202		if manifest.Hash != "" {
203			if !strings.EqualFold(calculated, manifest.Hash) {
204				return fmt.Errorf("checksum mismatch: expected %s, got %s", manifest.Hash, calculated)
205			}
206		} else {
207			manifest.Hash = calculated
208		}
209	
210		if err := os.MkdirAll(targetDir, 0o755); err != nil {
211			return fmt.Errorf("cannot create vendor dir: %w", err)
212		}
213		// Archive entries are untrusted input. Every destination must resolve
214		// (through symlinks already present in the vendor directory) strictly
215		// inside the resolved target directory.
216		root, err := resolvePath(targetDir, true)
217		if err != nil {
218			return fmt.Errorf("cannot resolve vendor dir: %w", err)
219		}
220	
221		grPre, err := gzip.NewReader(bytes.NewReader(data))
222		if err != nil {
223			return fmt.Errorf("failed to decompress gzip: %w", err)
224		}
225		defer func() { _ = grPre.Close() }()
226	
227		// Pre-scan headers to determine if bundle uses standard DMAA knowledge/ directory
228		// and whether files are wrapped in a single root directory (e.g. GitHub archive repo-main/).
229		// Entries that would escape are refused here, before anything is written.
230		hasKnowledgeDir := false
231		rootWrapper := ""
232		firstRootChecked := false
233		var extracted []string
234	
235		trPre := tar.NewReader(grPre)
236		for {
237			hdr, err := trPre.Next()
238			if err == io.EOF {
239				break
240			}
241			if err != nil {
242				return fmt.Errorf("tar pre-scan error: %w", err)
243			}
244			cleanName := filepath.ToSlash(filepath.Clean(hdr.Name))
245			if cleanName == "." {
246				continue
247			}
248			if cleanName == ".." || strings.HasPrefix(cleanName, "../") || strings.HasPrefix(cleanName, "/") || filepath.IsAbs(hdr.Name) || filepath.VolumeName(hdr.Name) != "" {
249				return fmt.Errorf("path traversal attempt: archive entry %q escapes the bundle directory", hdr.Name)
250			}
251			if hdr.Typeflag == tar.TypeDir || hdr.Typeflag == tar.TypeReg {
252				extracted = append(extracted, cleanName)
253			}
254	
255			parts := strings.Split(cleanName, "/")
256			if !firstRootChecked {
257				if len(parts) > 1 || hdr.Typeflag == tar.TypeDir {
258					rootWrapper = parts[0]
259				}
260				firstRootChecked = true
261			} else if rootWrapper != "" && parts[0] != rootWrapper {
262				rootWrapper = ""
263			}
264	
265			if cleanName == "knowledge/index.md" || strings.HasSuffix(cleanName, "/knowledge/index.md") {
266				hasKnowledgeDir = true
267			}
268		}
269	
270		// destination maps an archive entry to its path relative to targetDir, or
271		// reports false for entries that are not extracted.
272		destination := func(cleanName string) (string, bool) {
273			var relDest string
274			if hasKnowledgeDir {
275				// Extract only contents of knowledge/ directory; skip all non-knowledge repo files
276				idx := strings.Index(cleanName, "/knowledge/")
277				if idx != -1 {
278					relDest = cleanName[idx+len("/knowledge/"):]
279				} else if strings.HasPrefix(cleanName, "knowledge/") {
280					relDest = cleanName[len("knowledge/"):]
281				} else {
282					return "", false
283				}
284			} else {
285				// Pure bundle fallback: strip single root wrapper (e.g. repo-main/) if present
286				if rootWrapper != "" {
287					if cleanName == rootWrapper {
288						return "", false
289					}
290					if strings.HasPrefix(cleanName, rootWrapper+"/") {
291						relDest = cleanName[len(rootWrapper)+1:]
292					} else {
293						relDest = cleanName
294					}
295				} else {
296					relDest = cleanName
297				}
298			}
299	
300			relDest = filepath.Clean(relDest)
301			if relDest == "" || relDest == "." || relDest == ".." || strings.HasPrefix(relDest, "..") || filepath.IsAbs(relDest) {
302				return "", false
303			}
304			return relDest, true
305		}
306	
307		// containedDest checks the lexical join and then the symlink-resolved
308		// destination, which is what the write goes to.
309		containedDest := func(relDest string) (string, error) {
310			destPath := filepath.Join(targetDir, filepath.FromSlash(relDest))
311			cleanDestPath := filepath.Clean(destPath)
312			cleanTargetDir := filepath.Clean(targetDir)
313			if !strings.HasPrefix(cleanDestPath, cleanTargetDir+string(filepath.Separator)) && cleanDestPath != cleanTargetDir {
314				return "", fmt.Errorf("path traversal attempt: %s", relDest)
315			}
316			resolved, err := containedPath(root, filepath.Join(root, filepath.FromSlash(relDest)), true, fmt.Sprintf("archive entry %q", relDest))
317			if err != nil {
318				return "", fmt.Errorf("path traversal attempt: %w", err)
319			}
320			return resolved, nil
321		}
322	
323		// Resolve every destination before writing anything, so one escaping entry
324		// refuses the whole archive instead of leaving it half-extracted.
325		for _, name := range extracted {
326			if relDest, ok := destination(name); ok {
327				if _, err := containedDest(relDest); err != nil {
328					return err
329				}
330			}
331		}
332	
333		gr, err := gzip.NewReader(bytes.NewReader(data))
334		if err != nil {
335			return fmt.Errorf("failed to decompress gzip: %w", err)
336		}
337		defer func() { _ = gr.Close() }()
338	
339		tr := tar.NewReader(gr)
340		for {
341			hdr, err := tr.Next()
342			if err == io.EOF {
343				break
344			}
345			if err != nil {
346				return fmt.Errorf("tar extract error: %w", err)
347			}
348	
349			cleanName := filepath.ToSlash(filepath.Clean(hdr.Name))
350			if cleanName == "." || cleanName == ".." || strings.HasPrefix(cleanName, "../") {
351				continue
352			}
353	
354			relDest, ok := destination(cleanName)
355			if !ok {
356				continue
357			}
358	
359			switch hdr.Typeflag {
360			case tar.TypeDir:
361				cleanDestPath, err := containedDest(relDest)
362				if err != nil {
363					return err
364				}
365				if err := os.MkdirAll(cleanDestPath, 0o755); err != nil {
366					return err
367				}
368			case tar.TypeReg:
369				cleanDestPath, err := containedDest(relDest)
370				if err != nil {
371					return err
372				}
373				if err := os.MkdirAll(filepath.Dir(cleanDestPath), 0o755); err != nil {
374					return err
375				}
376				// #nosec G304 -- cleanDestPath is resolved and strictly verified to reside within the resolved target dir
377				outFile, err := os.OpenFile(cleanDestPath, os.O_CREATE|os.O_RDWR|os.O_TRUNC, hdr.FileInfo().Mode())
378				if err != nil {
379					return err
380				}
381				// #nosec G110 -- bounded extraction limit (50MB) mitigates decompression bombs
382				const maxExtractBytes = 50 * 1024 * 1024
383				if _, err := io.Copy(outFile, io.LimitReader(tr, maxExtractBytes)); err != nil {
384					_ = outFile.Close()
385					return err
386				}
387				_ = outFile.Close()
388			}
389		}
390	
391		return nil
392	}
