105	func WriteLockfile(path string, lf *Lockfile) error {
106		cleanPath := filepath.Clean(path)
107		// #nosec G304 -- lockfile path is provided by caller or default workspace okf.lock
108		f, err := os.Create(cleanPath)
109		if err != nil {
110			return err
111		}
112		defer func() { _ = f.Close() }()
113	
114		w := bufio.NewWriter(f)
115		if _, err := fmt.Fprintf(w, "# okf.lock - Generated by OKF Agent Memory. DO NOT EDIT MANUALLY.\n"); err != nil {
116			return err
117		}
118		if _, err := fmt.Fprintf(w, "version: %d\n", lf.Version); err != nil {
119			return err
120		}
121		if _, err := fmt.Fprintf(w, "bundles:\n"); err != nil {
122			return err
123		}
124		for _, b := range lf.Bundles {
125			if _, err := fmt.Fprintf(w, "  - id: %q\n", b.ID); err != nil {
126				return err
127			}
128			if _, err := fmt.Fprintf(w, "    source: %q\n", b.Source); err != nil {
