21	func serveBody(body []byte) roundTripFunc {
22		return func(req *http.Request) (*http.Response, error) {
23			return &http.Response{StatusCode: http.StatusOK, Status: "200 OK", Header: make(http.Header), Body: io.NopCloser(bytes.NewReader(body))}, nil
24		}
25	}
