27	type tarEntry struct {
28		name, body string
29		typeflag   byte
30	}
31	
32	// orderedTarGz builds an archive with entries in the given order (the order
33	// matters for the all-or-nothing checks).
34	func orderedTarGz(t *testing.T, entries ...tarEntry) []byte {
35		t.Helper()
36		var buf bytes.Buffer
37		gw := gzip.NewWriter(&buf)
38		tw := tar.NewWriter(gw)
39		for _, e := range entries {
40			typeflag := e.typeflag
41			if typeflag == 0 {
42				typeflag = tar.TypeReg
43			}
44			hdr := &tar.Header{Name: e.name, Mode: 0o644, Size: int64(len(e.body)), Typeflag: typeflag}
45			if typeflag == tar.TypeDir {
46				hdr.Mode, hdr.Size = 0o755, 0
47			}
48			if err := tw.WriteHeader(hdr); err != nil {
49				t.Fatal(err)
50			}
51			if typeflag == tar.TypeReg {
52				if _, err := tw.Write([]byte(e.body)); err != nil {
53					t.Fatal(err)
54				}
55			}
56		}
57		if err := tw.Close(); err != nil {
58			t.Fatal(err)
59		}
60		if err := gw.Close(); err != nil {
61			t.Fatal(err)
62		}
63		return buf.Bytes()
64	}
