66	func extractInto(t *testing.T, archive []byte, targetDir string) error {
67		t.Helper()
68		client := registry.NewClient("https://registry.test")
69		client.HTTPClient.Transport = serveBody(archive)
70		return client.DownloadAndExtract(&registry.BundleManifest{ID: "acme/rules", Version: "1.0.0", DownloadURL: "https://registry.test/b.tar.gz"}, targetDir)
