73	func listFiles(t *testing.T, dir string) []string {
74		t.Helper()
75		var out []string
76		_ = filepath.WalkDir(dir, func(p string, d os.DirEntry, err error) error {
77			if err == nil && p != dir {
78				rel, _ := filepath.Rel(dir, p)
79				out = append(out, filepath.ToSlash(rel))
80			}
81			return nil
82		})
83		return out
84	}
