164			if err := os.MkdirAll(target, 0o755); err != nil {
165				t.Fatal(err)
166			}
167			if err := os.WriteFile(victim, []byte("user data"), 0o644); err != nil {
168				t.Fatal(err)
169			}
170			if err := os.Symlink(victim, filepath.Join(target, "index.md")); err != nil {
171				t.Fatal(err)
172			}
173			err := extractInto(t, orderedTarGz(t, tarEntry{name: "index.md", body: "pwn"}), target)
174			if b, _ := os.ReadFile(victim); string(b) != "user data" {
