178				t.Fatalf("expected write through file symlink to be refused, got %v", err)
179			}
180		})
181		t.Run("directory entry through symlink", func(t *testing.T) {
182			base := t.TempDir()
183			target, outside := filepath.Join(base, "vendor", "rules"), filepath.Join(base, "outside")
184			if err := os.MkdirAll(target, 0o755); err != nil {
