191				t.Fatal(err)
192			}
193			// index.md first, so the archive has no single root wrapper to strip.
194			err := extractInto(t, orderedTarGz(t, tarEntry{name: "index.md", body: "# ok"}, tarEntry{name: "sub/nested/", typeflag: tar.TypeDir}), target)
195			if files := listFiles(t, outside); len(files) != 0 {
196				t.Fatalf("outside directory written: %v", files)
197			}
198			if err == nil {
